#!/usr/bin/env node
// Writes the index of shared code (first doc sentence of every export) into AGENTS.md.
// `--check` fails when the block is stale, an export has no doc sentence, or the block is too big.
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join, relative, sep } from "node:path";
import ts from "typescript";

const BEGIN = "<!-- BEGIN:agent-index -->";
const END = "<!-- END:agent-index -->";
const MAX_CHARS = 8000;
const AGENTS = "AGENTS.md";
const INTRO =
  "Generated by `pnpm index` from the first sentence of each export's doc comment; do not edit by hand. Before writing a component, hook, helper or use case, find it here and read its file; a UI package index in this file comes before `@repo/ui`. If nothing fits, say what you looked for, then add it to the right package with a one-sentence doc comment.";

const check = process.argv.includes("--check");

const listDirs = (dir) =>
  existsSync(dir) ? readdirSync(dir).filter((name) => statSync(join(dir, name)).isDirectory()) : [];

const walk = (dir) =>
  existsSync(dir)
    ? readdirSync(dir, { withFileTypes: true }).flatMap((entry) =>
        entry.isDirectory() ? walk(join(dir, entry.name)) : [join(dir, entry.name)],
      )
    : [];

// Indexed roots: [directory, package name when the import path comes from `exports`].
const roots = [
  ...["atoms", "molecules", "organisms", "templates", "lib"].map((d) => [
    join("packages/ui/src", d),
    "packages/ui",
  ]),
  ...["domain", "data", "i18n"].map((d) => [join("packages/shared/src", d), "packages/shared"]),
  ...listDirs("apps").flatMap((app) => [
    ...listDirs(join("apps", app, "src/features")).map((f) => [
      join("apps", app, "src/features", f, "application"),
      null,
    ]),
    [join("apps", app, "src/shared"), null],
  ]),
];

const exportMaps = new Map();
const packageExports = (pkgDir) => {
  if (!exportMaps.has(pkgDir)) {
    const pkg = JSON.parse(readFileSync(join(pkgDir, "package.json"), "utf8"));
    const entries = Object.entries(pkg.exports ?? {}).map(([subpath, target]) => {
      const [prefix, suffix = ""] = target.split("*");
      return { name: pkg.name, subpath, target, prefix, suffix, wild: target.includes("*") };
    });
    // Exact entries win over wildcards, then the longest prefix.
    entries.sort((a, b) => a.wild - b.wild || b.prefix.length - a.prefix.length);
    exportMaps.set(pkgDir, entries);
  }
  return exportMaps.get(pkgDir);
};

const importPath = (file, pkgDir) => {
  if (!pkgDir)
    return file
      .split(sep)
      .join("/")
      .replace(/\.tsx?$/, "");
  const rel = `./${relative(pkgDir, file).split(sep).join("/")}`;
  for (const entry of packageExports(pkgDir)) {
    if (!entry.wild) {
      if (entry.target === rel) return `${entry.name}/${entry.subpath.slice(2)}`;
    } else if (rel.startsWith(entry.prefix) && rel.endsWith(entry.suffix)) {
      const star = rel.slice(entry.prefix.length, rel.length - entry.suffix.length);
      return `${entry.name}/${entry.subpath.replace("*", star).slice(2)}`;
    }
  }
  return null;
};

const firstSentence = (node) => {
  const doc = node.jsDoc?.at(-1);
  const text = doc ? ts.getTextOfJSDocComment(doc.comment) : undefined;
  const flat = text?.replace(/\s+/g, " ").trim();
  if (!flat) return null;
  const end = flat.indexOf(". ");
  const sentence = end === -1 ? flat : flat.slice(0, end + 1);
  return sentence.endsWith(".") ? sentence : `${sentence}.`;
};

const bindingNames = (name) =>
  ts.isIdentifier(name)
    ? [name.text]
    : name.elements.flatMap((el) => (ts.isOmittedExpression(el) ? [] : bindingNames(el.name)));

const exportedNames = (stmt) => {
  if (ts.isVariableStatement(stmt))
    return stmt.declarationList.declarations.flatMap((d) => bindingNames(d.name));
  if (ts.isExportAssignment(stmt)) return stmt.isExportEquals ? [] : ["default"];
  if (
    (ts.isFunctionDeclaration(stmt) ||
      ts.isClassDeclaration(stmt) ||
      ts.isInterfaceDeclaration(stmt) ||
      ts.isTypeAliasDeclaration(stmt) ||
      ts.isEnumDeclaration(stmt)) &&
    stmt.name
  ) {
    return [stmt.name.text];
  }
  return [];
};

const isExported = (stmt) =>
  ts.isExportAssignment(stmt) ||
  (ts.canHaveModifiers(stmt) &&
    ts.getModifiers(stmt)?.some((m) => m.kind === ts.SyntaxKind.ExportKeyword));

const problems = [];
const lines = [];
const files = roots
  .flatMap(([dir, pkgDir]) => walk(dir).map((file) => [file, pkgDir]))
  .filter(([file]) => /\.tsx?$/.test(file) && !/\.(test|spec)\.|\.d\.ts$/.test(file));

for (const [file, pkgDir] of files) {
  const path = importPath(file, pkgDir);
  if (!path) {
    problems.push(`${file}: not reachable through the package "exports" map`);
    continue;
  }
  const source = ts.createSourceFile(
    file,
    readFileSync(file, "utf8"),
    ts.ScriptTarget.Latest,
    true,
  );
  const seen = new Set();
  const entries = [];
  for (const stmt of source.statements) {
    if (!isExported(stmt)) continue;
    const sentence = firstSentence(stmt);
    for (const name of exportedNames(stmt)) {
      if (seen.has(name)) continue;
      seen.add(name);
      if (sentence) {
        // Consecutive names with the same sentence (destructured exports) share one entry.
        const last = entries.at(-1);
        if (last?.sentence === sentence) last.names.push(name);
        else entries.push({ names: [name], sentence });
      } else {
        const { line } = source.getLineAndCharacterOfPosition(stmt.getStart(source));
        problems.push(`${file}:${line + 1} ${name} has no doc comment sentence`);
      }
    }
  }
  if (entries.length > 0)
    lines.push([
      path,
      `${path}|${entries.map((e) => `${e.names.join(", ")}: ${e.sentence}`).join(" ")}`,
    ]);
}

lines.sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));

const block = [
  BEGIN,
  "",
  "## Index of shared code",
  "",
  INTRO,
  "",
  "```text",
  ...lines.map(([, line]) => line),
  "```",
  "",
  END,
].join("\n");

const current = readFileSync(AGENTS, "utf8");
const pattern = new RegExp(`${BEGIN}[\\s\\S]*?${END}`);

if (check) {
  if (block.length > MAX_CHARS) {
    problems.push(`index block is ${block.length} characters; the limit is ${MAX_CHARS}`);
  }
  if (!pattern.test(current) || current.match(pattern)[0] !== block) {
    problems.push(`${AGENTS} index block is stale; run \`pnpm index\``);
  }
  if (problems.length > 0) {
    for (const problem of problems) console.error(problem);
    process.exit(1);
  }
  console.log(`index: ${AGENTS} block is current (${block.length} characters)`);
} else {
  for (const problem of problems) console.error(problem);
  let next;
  if (pattern.test(current)) next = current.replace(pattern, () => block);
  else {
    // First run: place the block after the `## Structure` section.
    const heading = current.indexOf("\n## Structure");
    const after = heading === -1 ? -1 : current.indexOf("\n## ", heading + 1);
    if (after === -1) next = `${current.trimEnd()}\n\n${block}\n`;
    else next = `${current.slice(0, after).trimEnd()}\n\n${block}\n${current.slice(after)}`;
  }
  writeFileSync(AGENTS, next);
  console.log(`index: wrote ${lines.length} files (${block.length} characters)`);
  if (problems.length > 0) process.exit(1);
}
